import copy

TABLES = ['items', 'assignments', 'reviews', 'expert_versions']

def assignment_overlap(snapshot, options):
    from collections import Counter
    counts = Counter(r['supplier'] for r in snapshot['assignments'])
    seen = {}
    for review in snapshot['reviews']:
        seen.setdefault(review['item_id'], set()).add(review['supplier'])
    overlap = sum(len(suppliers) > 1 for suppliers in seen.values())
    return {'items': len(snapshot['items']), 'assignments': len(snapshot['assignments']),
            'reviews': len(snapshot['reviews']), 'expert_items': len(snapshot['expert_versions']),
            'suppliers': dict(counts), 'overlapped_items': overlap,
            'abstentions': sum(r['label'] == 'abstain' for r in snapshot['reviews'])}

